````tsx
   0 'use client';
   1 
   2 import { useEditorStore } from '@/modules/ai-content/adapters/state/use-editor-store';
   3 import { BubbleMenu, EditorContent, useEditor, type Editor } from '@tiptap/react';
   4 import React, { useState } from 'react';
   5 import { editorExtensions, handleHtmlPaste, handlePlainPaste } from '@/modules/ai-content/infrastructure/editor/tiptap-extensions';
   6 import { useService } from '@/hooks/util/use-service';
   7 import { IMarkdownServiceToken } from '@/infrastructure/di/tokens';
   8 import { IMarkdownService } from '@/modules/ai-content/domain/services/IMarkdownService';
   9 import { Button } from '@/components/ui/button';
  10 import { ContextualToolbar } from '@/modules/ai-content/infrastructure/editor/editor/ToolBar';
  11 import { cn } from '@/infrastructure/utils/cn';
  12 import { PROSE_CLASSES } from './markdown-styles';
  13 
  14 interface MarkdownEditorProps {
  15   content: string;
  16   onChange: (markdown: string) => void;
  17   onDebouncedChange?: (markdown: string) => void;
  18   onActiveItemDetect?: (headingText: string | null) => void;
  19   editorClassName?: string;
  20   debounceMs?: number;
  21 }
  22 
  23 const MarkdownEditorComponent = ({
  24   content,
  25   onChange,
  26   onDebouncedChange,
  27   onActiveItemDetect,
  28   editorClassName,
  29   debounceMs = 1000
  30 }: MarkdownEditorProps) => {
  31   const { setActiveEditor, updateSelectionState } = useEditorStore();
  32   const markdownService = useService<IMarkdownService>(IMarkdownServiceToken);
  33   const bubbleMenuId = React.useId();
  34 
  35   const editor = useEditor({
  36     extensions: editorExtensions(bubbleMenuId, markdownService),
  37     content: markdownService.toHtml(content),
  38     onSelectionUpdate: ({ editor }) => {
  39       if (!onActiveItemDetect) return;
  40       // Find nearest heading node above cursor position
  41       const { $anchor } = editor.state.selection;
  42       let headingText: string | null = null;
  43       for (let depth = $anchor.depth; depth >= 0; depth--) {
  44         const node = $anchor.node(depth);
  45         if (node.type.name === 'heading') {
  46           headingText = node.textContent;
  47           break;
  48         }
  49       }
  50       // Walk backwards through doc to find nearest heading before cursor
  51       if (!headingText) {
  52         const pos = $anchor.pos;
  53         editor.state.doc.nodesBetween(0, pos, (node) => {
  54           if (node.type.name === 'heading') {
  55             headingText = node.textContent;
  56           }
  57         });
  58       }
  59       onActiveItemDetect(headingText);
  60     },
  61     onUpdate: ({ editor }) => {
  62       // Notify the store about selection/state changes
  63       updateSelectionState(editor);
  64 
  65       if (onDebouncedChange) {
  66         const markdown = markdownService.toMarkdown(editor.getHTML());
  67         // Simple manual debounce
  68         const timer = (editor as any)._updateTimer;
  69         if (timer) clearTimeout(timer);
  70         (editor as any)._updateTimer = setTimeout(() => {
  71           onDebouncedChange(markdown);
  72         }, debounceMs);
  73       }
  74     },
  75     onBlur: ({ editor }) => {
  76       const markdown = markdownService.toMarkdown(editor.getHTML());
  77       onChange(markdown);
  78     },
  79     editorProps: {
  80       attributes: {
  81         class: cn(PROSE_CLASSES, editorClassName),
  82       },
  83       handlePaste: (view, event, slice): boolean => {
  84         const text = event.clipboardData?.getData('text/plain');
  85         const html = event.clipboardData?.getData('text/html');
  86 
  87         if (html) {
  88           void handleHtmlPaste(editor!, html);
  89           return true;
  90         }
  91 
  92         if (text) {
  93           void handlePlainPaste(editor!, text, markdownService);
  94           return true;
  95         }
  96 
  97         return false;
  98       },
  99     },
 100     immediatelyRender: false,
 101   });
 102 
 103   // Sync external content changes
 104   React.useEffect(() => {
 105     if (!editor || editor.isDestroyed) return;
 106 
 107     const currentHtml = editor.getHTML();
 108     const newHtml = markdownService.toHtml(content);
 109 
 110     // Only update if content is actually different to prevent cursor jumping
 111     // and only if the change came from outside (not while typing)
 112     if (newHtml !== currentHtml && !editor.isFocused) {
 113       editor.commands.setContent(newHtml, false);
 114       updateSelectionState(editor);
 115     }
 116   }, [content, editor, markdownService, updateSelectionState]);
 117 
 118   // Set the global editor instance
 119   React.useEffect(() => {
 120     if (editor) {
 121       setActiveEditor(editor);
 122       updateSelectionState(editor);
 123     }
 124     return () => {
 125       setActiveEditor(null);
 126     };
 127   }, [editor, setActiveEditor, updateSelectionState]);
 128 
 129   const handleWrapperClick = (event: React.MouseEvent<HTMLDivElement>) => {
 130     if (editor && event.target === event.currentTarget) {
 131       editor.chain().focus().run();
 132     }
 133   };
 134 
 135   return (
 136     <div className="relative text-base h-full">
 137       {editor && (
 138         <BubbleMenu
 139           editor={editor}
 140           tippyOptions={{
 141             duration: 200,
 142             placement: 'top',
 143             animation: 'shift-away'
 144           }}
 145           pluginKey={bubbleMenuId}
 146           shouldShow={({ editor }) => !editor.state.selection.empty && !editor.isActive('image')}
 147         >
 148           {editor.isActive('table') ? (
 149             <div className="flex items-center gap-1.5 rounded-2xl border border-primary/10 bg-background/60 backdrop-blur-2xl p-1.5 shadow-2xl shadow-primary/5 transition-all duration-300">
 150               <div className="flex items-center gap-1 px-1">
 151                 <Button variant="ghost" size="sm" className="h-8 text-[9px] font-black uppercase tracking-widest px-2 rounded-lg" onClick={() => editor.chain().focus().addColumnBefore().run()}>+ Col</Button>
 152                 <Button variant="ghost" size="sm" className="h-8 text-[9px] font-black uppercase tracking-widest px-2 rounded-lg" onClick={() => editor.chain().focus().addRowBefore().run()}>+ Row</Button>
 153               </div>
 154               <div className="h-4 w-px bg-primary/10" />
 155               <Button
 156                 variant="ghost"
 157                 size="sm"
 158                 className="h-8 text-[9px] font-black uppercase tracking-widest px-2 rounded-lg text-destructive hover:bg-destructive/10 hover:text-destructive"
 159                 onClick={() => editor.chain().focus().deleteTable().run()}
 160               >
 161                 Delete Table
 162               </Button>
 163             </div>
 164           ) : (
 165             <ContextualToolbar editor={editor as Editor} />
 166           )}
 167         </BubbleMenu>
 168       )}
 169       <div
 170         className="rounded-b-lg p-0 min-h-[200px] h-full relative transition-colors duration-300"
 171         onClick={handleWrapperClick}
 172       >
 173         <EditorContent editor={editor} className="h-full" />
 174       </div>
 175     </div>
 176   );
 177 };
 178 
 179 const MarkdownEditor = React.memo(MarkdownEditorComponent);
 180 
 181 export default MarkdownEditor;
 182 
````

